-- =====================================================================
-- vrindavanmathuratrip: Temple CMS
-- Paste this whole file into the Supabase SQL editor and press Run. Run it once.
-- Generated by scripts/generate-temple-seed.ts. Edit that script, not this file.
--
-- 1. Adds "details" to Temple: darshan and aarti timings, address, map, routes,
--    gallery, nearby, related, festivals, custom sections and page layout.
--    Row shape: TempleDetails in src/lib/cms/temple-fields.ts.
-- 2. Adds the site's 21 existing temple guides as published rows, so every
--    /temples link keeps working and each guide can be edited in the CMS.
-- 3. Adds the /temples page copy from the PDF as the published "temples" page.
--
-- Safe to re-run: "on conflict do nothing" never overwrites a row you have edited.
-- Nothing is deleted, and Blog, Package and the other SitePage rows are not touched.
-- =====================================================================

alter table public."Temple" add column if not exists details jsonb not null default '{}'::jsonb;

insert into public."Temple" (title, location, slug, meta, schema, image, alt, subcontent, content, history, timing, bestvisit, journey, templeoverview, quickanswer, ataglance, whybook, faqs, details, status)
values
  ('Shri Banke Bihari Temple', 'Vrindavan', 'banke-bihari', '{"title":"Shri Banke Bihari Temple, Vrindavan: Timings & Guide","description":"The beating heart of Vrindavan — an intimate, joyful darshan of Thakur ji in his tribhanga pose. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Shri Banke Bihari Temple","description":"The beating heart of Vrindavan — an intimate, joyful darshan of Thakur ji in his tribhanga pose."}'::jsonb, 'photo:banke-bihari', 'Ornate facade of Shri Banke Bihari Temple rising above the lanes of Vrindavan', 'The beating heart of Vrindavan — an intimate, joyful darshan of Thakur ji in his tribhanga pose.', '', 'The deity of Banke Bihari ji is said to have appeared to the saint-musician Swami Haridas in Nidhivan, in answer to his devotional singing. For many years Thakur ji was worshipped in the grove before the present temple was built in the 1860s by devotees of the Goswami community that still serves here.

What makes darshan here unlike anywhere else is its tenderness. A curtain is drawn across the sanctum every few minutes, so that devotees do not gaze too long — the belief is that Bihari ji might be drawn away with a loving devotee. There are no bells and no conch; the mood is of a beloved child or friend rather than a distant king.

On Janmashtami night the rare mangala aarti takes place, and in the summer months the temple is decorated with intricate flower palaces known as Phool Bangla.', '<p>Hours were extended by the court-appointed temple committee from 30 September 2025, and a legal challenge to the change was reported. Many lists still show the older summer hours of 7:45 am – 12:00 noon and 5:30 – 9:30 pm.</p><p>There are no bells or conch here, and the curtain is drawn every few minutes. Mangla aarti is held only once a year, on Janmashtami night.</p>', '', '', '<p><strong>What it is known for.</strong> <strong>Banke Bihari Temple Vrindavan</strong> is the beating heart of the town. The deity is a dark, enchanting form of Krishna standing in the <em>tribhanga</em> pose (bent in three places), which is where the name <em>banke</em> comes from. Tradition says he was revealed to the saint-musician <strong>Swami Haridas</strong> at Nidhivan through the force of his singing, and that Radha and Krishna merged into this single form.</p><p><strong>The curtain (jhanki) darshan.</strong> This is the custom that surprises every first-timer. A curtain in front of the deity is drawn and opened again and again, so you receive darshan in glimpses. Brijwasis say that if you gaze at Bihari ji''s eyes without a break, he will captivate you and refuse to let you go. So the pujaris draw the curtain to protect devotees from overwhelming love. Once you know the story, the interruption becomes part of the blessing.</p><p><strong>Another unusual custom.</strong> There is no regular mangala aarti here, because Bihari ji is worshipped as a playful child who has spent the night in Raas and is allowed to sleep late. The special mangala aarti is held only on <strong>Janmashtami</strong>.</p>', '<p>Shri Banke Bihari Temple is in Vrindavan. The beating heart of Vrindavan — an intimate, joyful darshan of Thakur ji in his tribhanga pose. Usual darshan hours in summer: morning 7:00 am – 12:30 pm, evening 4:15 pm – 9:30 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"श्री बांके बिहारी मंदिर"},{"id":"g2","label":"Location","value":"Vrindavan"},{"id":"g3","label":"Type","value":"Radha Krishna Temple"},{"id":"g4","label":"Darshan","value":"Morning & evening darshan; closed in the afternoon"},{"id":"g5","label":"Dress code","value":"Modest Indian or covered clothing. Footwear is left outside — use the paid stands nearby."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What are the Banke Bihari Temple timings?","answer":"In summer, about 7:45 a.m. to noon and 5:30 to 9:30 p.m. In winter, about 8:45 a.m. to 1 p.m. and 4:30 to 8:30 p.m. Timings and crowd rules can be revised, so always reconfirm."},{"id":"q2","question":"Which temple should I visit first in Vrindavan?","answer":"For most pilgrims I recommend Banke Bihari first, on a weekday soon after opening, before the lanes fill up. Then visit the quieter Goswami temples, and keep Prem Mandir for the evening lights."},{"id":"q3","question":"Are phones allowed inside Mathura Vrindavan temples?","answer":"In many major temples, including Krishna Janmabhoomi and often Banke Bihari and Prem Mandir''s inner sanctum, mobile phones, cameras and bags are restricted. Lockers or cloakrooms are usually available nearby. Rules can change, so check on the day, or leave valuables in your vehicle or hotel."},{"id":"q4","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q5","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Radha Krishna Temple","featured":true,"sortOrder":"1","timingNote":"Morning & evening darshan; closed in the afternoon","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Morning","time":"7:00 am – 12:30 pm","note":""},{"id":"d2","season":"Summer","session":"Evening","time":"4:15 pm – 9:30 pm","note":""},{"id":"d3","season":"Winter","session":"Morning","time":"8:00 am – 1:45 pm","note":""},{"id":"d4","season":"Winter","session":"Evening","time":"4:00 pm – 9:15 pm","note":""}],"aarti":[{"id":"a1","season":"Summer","name":"Darshan opens","time":"7:00 am"},{"id":"a2","season":"Summer","name":"Shringar aarti","time":"7:10 am"},{"id":"a3","season":"Summer","name":"Rajbhog aarti","time":"12:25 pm"},{"id":"a4","season":"Summer","name":"Morning darshan closes","time":"12:30 pm"},{"id":"a5","season":"Summer","name":"Evening darshan opens","time":"4:15 pm"},{"id":"a6","season":"Summer","name":"Shayan aarti","time":"9:25 pm"},{"id":"a7","season":"Summer","name":"Darshan closes","time":"9:30 pm"},{"id":"a8","season":"Winter","name":"Shringar aarti · darshan opens","time":"8:00 am"},{"id":"a9","season":"Winter","name":"Rajbhog aarti","time":"1:30 pm"},{"id":"a10","season":"Winter","name":"Morning darshan closes","time":"1:45 pm"},{"id":"a11","season":"Winter","name":"Evening darshan opens","time":"4:00 pm"},{"id":"a12","season":"Winter","name":"Shayan aarti","time":"9:00 pm"},{"id":"a13","season":"Winter","name":"Darshan closes","time":"9:15 pm"}],"visiting":[{"id":"v1","label":"Dress code","value":"Modest Indian or covered clothing. Footwear is left outside — use the paid stands nearby."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Go on a weekday, in the first hour after opening. By mid-morning, especially on weekends, Ekadashi and Purnima, the approach lane is shoulder to shoulder. Leave phones, bags and cameras in your vehicle or hotel, because pickpocketing is real in crowds and phones are generally not permitted near the sanctum. Inside the hall, patience pays: moving gently towards the side often gives a longer, clearer look than the central crush. Ignore anyone who offers \"VIP darshan\" for cash in the lane. Elderly pilgrims should come with a family member or our team, as the lanes are narrow and we know the gentlest approach."},{"id":"t2","text":"Weekends, Ekadashi and festival days are extremely crowded; a weekday morning is calmest."},{"id":"t3","text":"Keep spectacles, phones and bags secure — the lanes are narrow and monkeys are bold."},{"id":"t4","text":"Seniors and children should avoid peak festival crowds; we can suggest quieter time slots."},{"id":"t5","text":"Phool Bangla decorations in summer evenings are worth timing your visit for."}],"goodToKnow":"","address":{"street":"","locality":"Vrindavan","city":"Vrindavan","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Shri Banke Bihari Temple Vrindavan","latitude":"","longitude":"","routes":[{"id":"r1","from":"Mathura","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days. A private car is the most comfortable choice."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"About 3 to 3.5 hours on the Yamuna Expressway in normal traffic, or a train to Mathura Junction and a 25 to 30 minute drive."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km to Mathura","how":"Around 1 to 1.5 hours to Mathura by road, then on to Vrindavan."},{"id":"r4","from":"Within Vrindavan","distance":"Short hops","how":"Cars cannot enter the narrow old-town lanes, so walk or take an e-rickshaw for the last stretch. Agree the fare before you sit."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"nidhivan"},{"id":"l2","slug":"radha-vallabh"},{"id":"l3","slug":"seva-kunj"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Prem Mandir', 'Vrindavan', 'prem-mandir', '{"title":"Prem Mandir, Vrindavan: Timings & Guide","description":"A shining white-marble temple of divine love, famous for its gardens and evening illumination. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Prem Mandir","description":"A shining white-marble temple of divine love, famous for its gardens and evening illumination."}'::jsonb, 'photo:prem-mandir-night', 'Prem Mandir in Vrindavan illuminated in blue and white lights at night', 'A shining white-marble temple of divine love, famous for its gardens and evening illumination.', '', 'Prem Mandir — the Temple of Love — was established by Jagadguru Shri Kripalu Ji Maharaj and opened to devotees in 2012. Built from Italian marble over more than a decade, its walls are carved with scenes from the lives of Radha Krishna and Sita Ram.

The surrounding gardens hold life-size tableaux of Krishna’s leelas: lifting Govardhan hill, the raas with the gopis, and the subduing of Kaliya naag. As dusk falls, the entire temple glows in slowly changing colours, and a musical fountain show is usually held in the evening.', '<p>A parikrama aarti is held at 5:00 am.</p>', '', '', '<p><strong>What it is known for.</strong> Founded by <strong>Jagadguru Kripalu Maharaj</strong> and opened to the public in <strong>2012</strong>, Prem Mandir is a modern marvel of white marble. Its walls are carved with scenes from Krishna''s life, from his birth in prison to the lifting of Govardhan and the Raas. Inside you will find Radha-Krishna and Sita-Ram. The sculpted gardens and tableaux outside make it a favourite with families.</p><p><strong>The evening lights.</strong> After sunset the whole structure glows in shifting colours, and the marble seems lit from within. A musical fountain and illumination show draws large crowds in the evening hours when it is running. I have seen this sight countless times and it still quietens me.</p>', '<p>Prem Mandir is in Vrindavan. A shining white-marble temple of divine love, famous for its gardens and evening illumination. Usual darshan hours in summer: morning 8:30 am – 12:00 noon, evening 4:30 pm – 8:30 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"प्रेम मंदिर"},{"id":"g2","label":"Location","value":"Vrindavan"},{"id":"g3","label":"Type","value":"Modern Temple"},{"id":"g4","label":"Darshan","value":"Open morning & evening; lights after sunset"},{"id":"g5","label":"Dress code","value":"Modest clothing. Shoes are deposited at the free counter near the entrance."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What are the Prem Mandir timings?","answer":"Roughly 5:30 a.m. to 12 noon and 4:30 to 8:30 p.m., with the evening light show after sunset. Schedules vary by season, so confirm before you go."},{"id":"q2","question":"Are phones allowed inside Mathura Vrindavan temples?","answer":"In many major temples, including Krishna Janmabhoomi and often Banke Bihari and Prem Mandir''s inner sanctum, mobile phones, cameras and bags are restricted. Lockers or cloakrooms are usually available nearby. Rules can change, so check on the day, or leave valuables in your vehicle or hotel."},{"id":"q3","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q4","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Modern Temple","featured":true,"sortOrder":"2","timingNote":"Open morning & evening; lights after sunset","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Morning","time":"8:30 am – 12:00 noon","note":""},{"id":"d2","season":"Summer","session":"Evening","time":"4:30 pm – 8:30 pm","note":"Light & fountain show 7:30 – 8:00 pm"},{"id":"d3","season":"Winter","session":"Morning","time":"8:30 am – 12:00 noon","note":""},{"id":"d4","season":"Winter","session":"Evening","time":"4:30 pm – 8:30 pm","note":"Light & fountain show 7:00 – 7:30 pm"}],"aarti":[{"id":"a1","season":"Summer","name":"Parikrama aarti","time":"5:00 am"},{"id":"a2","season":"Summer","name":"Bhog","time":"6:30 am"},{"id":"a3","season":"Summer","name":"Darshan opens · aarti","time":"8:30 am"},{"id":"a4","season":"Summer","name":"Bhog","time":"11:30 am"},{"id":"a5","season":"Summer","name":"Doors close","time":"12:00 noon"},{"id":"a6","season":"Summer","name":"Darshan reopens · aarti","time":"4:30 pm"},{"id":"a7","season":"Summer","name":"Bhog","time":"5:30 pm"},{"id":"a8","season":"Summer","name":"Parikrama","time":"7:00 pm"},{"id":"a9","season":"Summer","name":"Light & fountain show","time":"7:30 – 8:00 pm"},{"id":"a10","season":"Summer","name":"Shayan aarti","time":"8:10 pm"},{"id":"a11","season":"Summer","name":"Doors close","time":"8:30 pm"},{"id":"a12","season":"Winter","name":"Parikrama aarti","time":"5:00 am"},{"id":"a13","season":"Winter","name":"Bhog","time":"6:30 am"},{"id":"a14","season":"Winter","name":"Darshan opens · aarti","time":"8:30 am"},{"id":"a15","season":"Winter","name":"Bhog","time":"11:30 am"},{"id":"a16","season":"Winter","name":"Doors close","time":"12:00 noon"},{"id":"a17","season":"Winter","name":"Darshan reopens · aarti","time":"4:30 pm"},{"id":"a18","season":"Winter","name":"Bhog","time":"5:30 pm"},{"id":"a19","season":"Winter","name":"Parikrama","time":"7:00 pm"},{"id":"a20","season":"Winter","name":"Light & fountain show","time":"7:00 – 7:30 pm"},{"id":"a21","season":"Winter","name":"Shayan aarti","time":"8:10 pm"},{"id":"a22","season":"Winter","name":"Doors close","time":"8:30 pm"}],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing. Shoes are deposited at the free counter near the entrance."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Visit twice in one day if you can. Come in the afternoon light to study the carvings, then stay for the show. Arrive well before sunset, because the best moment is just after the sun goes down, when the sky still holds a little blue and the marble starts to glow. Weekends and festival evenings are packed, so allow extra time for entry and parking. Mobile phones are normally restricted inside the main sanctum, so use the lockers."},{"id":"t2","text":"Arrive about 30 minutes before sunset to see the temple in daylight and then lit up."},{"id":"t3","text":"Photography is generally allowed in the gardens but not inside the sanctum."},{"id":"t4","text":"It is a short drive from ISKCON on the Chhatikara road, so the two pair well in one evening."}],"goodToKnow":"The evening light and fountain show timing shifts with sunset — usually around 7:00 pm in summer and earlier in winter.","address":{"street":"","locality":"Vrindavan","city":"Vrindavan","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Prem Mandir Vrindavan","latitude":"","longitude":"","routes":[{"id":"r1","from":"Mathura","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days. A private car is the most comfortable choice."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"About 3 to 3.5 hours on the Yamuna Expressway in normal traffic, or a train to Mathura Junction and a 25 to 30 minute drive."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km to Mathura","how":"Around 1 to 1.5 hours to Mathura by road, then on to Vrindavan."},{"id":"r4","from":"Within Vrindavan","distance":"Short hops","how":"Cars cannot enter the narrow old-town lanes, so walk or take an e-rickshaw for the last stretch. Agree the fare before you sit."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"iskcon-krishna-balaram"},{"id":"l2","slug":"banke-bihari"},{"id":"l3","slug":"rangji"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('ISKCON Krishna-Balaram Mandir', 'Vrindavan', 'iskcon-krishna-balaram', '{"title":"ISKCON Krishna-Balaram Mandir, Vrindavan: Timings & Guide","description":"A serene temple of kirtan and aarti at Raman Reti, home to Krishna-Balaram and Radha-Shyamasundar. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"ISKCON Krishna-Balaram Mandir","description":"A serene temple of kirtan and aarti at Raman Reti, home to Krishna-Balaram and Radha-Shyamasundar."}'::jsonb, 'photo:iskcon', 'Decorated altar of Radha Krishna deities at ISKCON Vrindavan', 'A serene temple of kirtan and aarti at Raman Reti, home to Krishna-Balaram and Radha-Shyamasundar.', '', 'The Krishna-Balaram Mandir was opened in 1975 by A.C. Bhaktivedanta Swami Prabhupada, founder of the International Society for Krishna Consciousness. It stands at Raman Reti, the sandy forest where Krishna and Balaram are said to have played as children.

Three altars hold Gaura-Nitai, Krishna-Balaram and Radha-Shyamasundar. The courtyard is filled with continuous kirtan, and the marble samadhi of Srila Prabhupada sits beside the temple.', '<p>One published list gives mangla aarti at 5:00 am.</p><p>Published lists differ by a few minutes on some slots; one gives mangla aarti at 5:00 am.</p>', '', '', '<p><strong>What it is known for.</strong> Consecrated in <strong>1975</strong> and founded by <strong>A.C. Bhaktivedanta Swami Prabhupada</strong>, this white marble temple houses the deities of Krishna-Balaram, Radha-Shyamasundar and Gaura-Nitai. Srila Prabhupada''s samadhi sits in the courtyard, a quiet corner for reflection.</p><p><strong>The kirtan vibes.</strong> What I love most is the congregational singing. Devotees from many countries sing and dance in the courtyard, and even sceptical visitors often find themselves clapping along. The temple is clean, orderly and welcoming, which makes it a gentle first stop for families and foreign guests.</p>', '<p>ISKCON Krishna-Balaram Mandir is in Raman Reti, Vrindavan. A serene temple of kirtan and aarti at Raman Reti, home to Krishna-Balaram and Radha-Shyamasundar. Usual darshan hours: morning 4:30 am – 12:45 pm, evening 4:30 pm – 8:00 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"इस्कॉन कृष्ण-बलराम मंदिर"},{"id":"g2","label":"Location","value":"Raman Reti, Vrindavan"},{"id":"g3","label":"Type","value":"Modern Temple"},{"id":"g4","label":"Darshan","value":"Early mangala aarti; open till late evening"},{"id":"g5","label":"Dress code","value":"Modest clothing; shoes off at the counter. Bags may be checked at the gate."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q2","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Modern Temple","featured":false,"sortOrder":"3","timingNote":"Early mangala aarti; open till late evening","stats":[],"darshan":[{"id":"d1","season":"","session":"Morning","time":"4:30 am – 12:45 pm","note":""},{"id":"d2","season":"","session":"Evening","time":"4:30 pm – 8:00 pm","note":""}],"aarti":[{"id":"a1","season":"","name":"Mangla aarti","time":"4:30 am"},{"id":"a2","season":"","name":"Guru puja","time":"7:15 am"},{"id":"a3","season":"","name":"Bhagavatam class","time":"7:30 am"},{"id":"a4","season":"","name":"Shringar aarti","time":"8:30 am"},{"id":"a5","season":"","name":"Rajbhog aarti","time":"12:00 noon"},{"id":"a6","season":"","name":"Doors reopen · dhoop aarti","time":"4:30 pm"},{"id":"a7","season":"","name":"Sandhya aarti","time":"6:30 pm"},{"id":"a8","season":"","name":"Gita class","time":"7:30 pm"},{"id":"a9","season":"","name":"Shayan aarti","time":"8:00 pm"}],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; shoes off at the counter. Bags may be checked at the gate."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Come for the evening aarti and kirtan, which have a different mood from the old Goswami temples. If you have time, take the temple prasadam, which is simple, hygienic and satvik. Dress modestly, and walk through the bookshop and museum if you are curious about Vaishnava philosophy."},{"id":"t2","text":"The early mangala aarti (around 4:30 am) is a beautiful, unhurried experience."},{"id":"t3","text":"The guesthouse restaurant serves simple sattvic meals."},{"id":"t4","text":"A good first stop for families — it is spacious and well organised."}],"goodToKnow":"","address":{"street":"","locality":"Raman Reti, Vrindavan","city":"Vrindavan","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"ISKCON Sri Sri Krishna Balaram Mandir Vrindavan","latitude":"","longitude":"","routes":[{"id":"r1","from":"Mathura","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days. A private car is the most comfortable choice."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"About 3 to 3.5 hours on the Yamuna Expressway in normal traffic, or a train to Mathura Junction and a 25 to 30 minute drive."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km to Mathura","how":"Around 1 to 1.5 hours to Mathura by road, then on to Vrindavan."},{"id":"r4","from":"Within Vrindavan","distance":"Short hops","how":"Cars cannot enter the narrow old-town lanes, so walk or take an e-rickshaw for the last stretch. Agree the fare before you sit."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"prem-mandir"},{"id":"l2","slug":"rangji"},{"id":"l3","slug":"banke-bihari"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Nidhivan', 'Vrindavan', 'nidhivan', '{"title":"Nidhivan, Vrindavan: Timings & Guide","description":"A mysterious tulsi grove where Radha Krishna are believed to perform raas leela every night. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Nidhivan","description":"A mysterious tulsi grove where Radha Krishna are believed to perform raas leela every night."}'::jsonb, 'photo:nidhivan', 'Twisted tulsi trees inside the sacred grove of Nidhivan, Vrindavan', 'A mysterious tulsi grove where Radha Krishna are believed to perform raas leela every night.', '', 'Nidhivan is a walled grove of short, twisted tulsi trees in the old part of Vrindavan. Local belief holds that Radha and Krishna come here each night for the raas leela, so the gates are closed after the evening aarti and no one stays inside.

Inside is the Rang Mahal, where a bed and adornments are prepared for the divine couple every evening, and the spot where Banke Bihari ji appeared to Swami Haridas. The saint’s samadhi is also here.', '<p>Gates close after the evening aarti; no one stays inside at night.</p>', '', '', '<p><strong>What it is known for.</strong> Nidhivan is the place I take guests when they ask me, "Where is the real Vrindavan?" It is a small, enclosed grove of low, twisted trees, locally believed to be wild tulsi, growing in pairs. It does not look grand. But step in quietly and you feel a stillness unlike anywhere else in town.</p><p><strong>The sacred grove and the Raas Leela legend.</strong> Braj tradition holds that every night Radha, Krishna and the gopis return to Nidhivan to dance the divine <strong>Raas</strong>, and that the trees become gopis at night and turn back into trees by morning. For this reason the grove is closed after dusk, and local belief says nothing living stays within overnight. Inside stands the <strong>Rang Mahal</strong>. Each evening the priests lay out items for Radha''s adornment, along with paan, sweets and water, and lock the doors. Devotees say the offerings are found disturbed in the morning.</p><p>Brijwasis also tell stories of those who tried to watch the grove at night and met misfortune, and they tell them with complete seriousness. I do not argue anyone into belief or out of it. I tell you what Braj has believed for centuries, and I invite you to stand quietly, close your eyes and let your own heart decide.</p><p><strong>Nearby.</strong> <strong><a href="/temples/seva-kunj">Seva Kunj</a></strong>, believed to be where Radha-Krishna rested after the Raas, and the samadhi of Swami Haridas. I always take guests to all three together.</p>', '<p>Nidhivan is in Vrindavan. A mysterious tulsi grove where Radha Krishna are believed to perform raas leela every night. Usual darshan hours in summer: morning 6:00 am – 12:30 pm, evening 4:00 pm – 8:00 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"निधिवन"},{"id":"g2","label":"Location","value":"Vrindavan"},{"id":"g3","label":"Type","value":"Sacred Grove"},{"id":"g4","label":"Darshan","value":"Daytime only; closed after evening aarti"},{"id":"g5","label":"Dress code","value":"Modest clothing; shoes are left at the entrance."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"Why is Nidhivan closed at night?","answer":"Tradition holds that Radha, Krishna and the gopis perform the Raas Leela in the grove every night, and nobody is allowed to stay. The grove closes at dusk and reopens in the morning."},{"id":"q2","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q3","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Sacred Grove","featured":false,"sortOrder":"4","timingNote":"Daytime only; closed after evening aarti","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Morning","time":"6:00 am – 12:30 pm","note":""},{"id":"d2","season":"Summer","session":"Evening","time":"4:00 pm – 8:00 pm","note":""},{"id":"d3","season":"Winter","session":"Morning","time":"6:00 am – 12:00 noon","note":""},{"id":"d4","season":"Winter","session":"Evening","time":"4:00 pm – 7:00 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; shoes are left at the entrance."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Go early in the morning when the grove is silent and the light is soft. Do not leave it for the end of the day, because it closes at dusk and there is no \"night entry,\" whatever anyone tells you. Keep your voice low and follow the photography signs. Hold your glasses and snacks carefully, as the monkeys here are experts."},{"id":"t2","text":"Hold on to spectacles and phones — the monkeys here are notorious."},{"id":"t3","text":"Local guides inside often ask for donations; it is fine to politely decline."},{"id":"t4","text":"It is a five-minute walk from Banke Bihari, so most people combine the two."}],"goodToKnow":"","address":{"street":"","locality":"Vrindavan","city":"Vrindavan","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Nidhivan Vrindavan","latitude":"","longitude":"","routes":[{"id":"r1","from":"Mathura","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days. A private car is the most comfortable choice."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"About 3 to 3.5 hours on the Yamuna Expressway in normal traffic, or a train to Mathura Junction and a 25 to 30 minute drive."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km to Mathura","how":"Around 1 to 1.5 hours to Mathura by road, then on to Vrindavan."},{"id":"r4","from":"Within Vrindavan","distance":"Short hops","how":"Cars cannot enter the narrow old-town lanes, so walk or take an e-rickshaw for the last stretch. Agree the fare before you sit."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"banke-bihari"},{"id":"l2","slug":"seva-kunj"},{"id":"l3","slug":"radha-vallabh"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Seva Kunj', 'Vrindavan', 'seva-kunj', '{"title":"Seva Kunj, Vrindavan: Timings & Guide","description":"A quiet sacred garden where Krishna is said to have served Radha — with Lalita Kund and the Rang Mahal. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Seva Kunj","description":"A quiet sacred garden where Krishna is said to have served Radha — with Lalita Kund and the Rang Mahal."}'::jsonb, 'photo:seva-kunj', 'Shady trees in the sacred garden of Seva Kunj, Vrindavan', 'A quiet sacred garden where Krishna is said to have served Radha — with Lalita Kund and the Rang Mahal.', '', 'Also called Nikunjvan, Seva Kunj is a garden of dense, low trees where, according to tradition, Krishna lovingly served Radharani — combing her hair and pressing her feet. As at Nidhivan, the garden is closed at night out of respect for the divine pastimes believed to take place here.

Within the grounds are the small Rang Mahal shrine and Lalita Kund, said to have been created by Krishna for the thirsty gopi Lalita.', '<p>Closed at night, like Nidhivan.</p>', '', '', '', '<p>Seva Kunj is in Vrindavan. A quiet sacred garden where Krishna is said to have served Radha — with Lalita Kund and the Rang Mahal. Usual darshan hours in summer: morning 7:00 am – 12:00 noon, evening 6:30 pm – 9:00 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"सेवा कुंज"},{"id":"g2","label":"Location","value":"Vrindavan"},{"id":"g3","label":"Type","value":"Sacred Grove"},{"id":"g4","label":"Darshan","value":"Daytime only; closed at night"},{"id":"g5","label":"Dress code","value":"Modest clothing; shoes off at the gate."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q2","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Sacred Grove","featured":false,"sortOrder":"5","timingNote":"Daytime only; closed at night","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Morning","time":"7:00 am – 12:00 noon","note":""},{"id":"d2","season":"Summer","session":"Evening","time":"6:30 pm – 9:00 pm","note":""},{"id":"d3","season":"Winter","session":"Morning","time":"7:00 am – 12:00 noon","note":""},{"id":"d4","season":"Winter","session":"Evening","time":"4:30 pm – 6:30 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; shoes off at the gate."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Combine with Radha Vallabh temple, which is in the same lanes."},{"id":"t2","text":"Quieter in the late morning than right after opening."}],"goodToKnow":"","address":{"street":"","locality":"Vrindavan","city":"Vrindavan","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Seva Kunj Vrindavan","latitude":"","longitude":"","routes":[{"id":"r1","from":"Mathura","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days. A private car is the most comfortable choice."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"About 3 to 3.5 hours on the Yamuna Expressway in normal traffic, or a train to Mathura Junction and a 25 to 30 minute drive."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km to Mathura","how":"Around 1 to 1.5 hours to Mathura by road, then on to Vrindavan."},{"id":"r4","from":"Within Vrindavan","distance":"Short hops","how":"Cars cannot enter the narrow old-town lanes, so walk or take an e-rickshaw for the last stretch. Agree the fare before you sit."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"radha-vallabh"},{"id":"l2","slug":"nidhivan"},{"id":"l3","slug":"radha-raman"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Shri Radha Raman Temple', 'Vrindavan', 'radha-raman', '{"title":"Shri Radha Raman Temple, Vrindavan: Timings & Guide","description":"One of Vrindavan’s seven original Goswami temples, with a self-manifested shaligram deity. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Shri Radha Raman Temple","description":"One of Vrindavan’s seven original Goswami temples, with a self-manifested shaligram deity."}'::jsonb, 'photo:radha-raman', 'Silver altar and checkered marble floor inside Radha Raman Temple, Vrindavan', 'One of Vrindavan’s seven original Goswami temples, with a self-manifested shaligram deity.', '', 'Radha Raman ji is believed to have manifested from a shaligram shila worshipped by Gopal Bhatta Goswami, one of the great saints of the Gaudiya tradition, in 1542. Unlike many early deities of Vrindavan, Radha Raman ji never left the town during times of upheaval and has been worshipped here continuously.

The temple is also known for its kitchen hearth, which tradition says has been kept alight for close to five centuries. Seva is performed by descendants of the Goswami family in a refined, intimate style.', '', '', '', '', '<p>Shri Radha Raman Temple is in Vrindavan. One of Vrindavan’s seven original Goswami temples, with a self-manifested shaligram deity. Usual darshan hours in summer: morning 8:30 am – 12:30 pm, evening 6:00 pm – 8:30 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"श्री राधा रमण मंदिर"},{"id":"g2","label":"Location","value":"Vrindavan"},{"id":"g3","label":"Type","value":"Goswami Temple"},{"id":"g4","label":"Darshan","value":"Short morning & evening darshan windows"},{"id":"g5","label":"Dress code","value":"Modest Indian clothing is preferred; shoes off outside."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What are the seven Goswami temples of Vrindavan?","answer":"Govind Dev, Gopinath, Madan Mohan, Radha Raman, Radha Damodar, Radha Shyamsundar and Radha Gokulananda, established by the followers of Chaitanya Mahaprabhu. Some lists include Banke Bihari and Radha Vallabh as separately important temples."},{"id":"q2","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q3","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Goswami Temple","featured":false,"sortOrder":"6","timingNote":"Short morning & evening darshan windows","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Morning","time":"8:30 am – 12:30 pm","note":""},{"id":"d2","season":"Summer","session":"Evening","time":"6:00 pm – 8:30 pm","note":""},{"id":"d3","season":"Winter","session":"Morning","time":"8:30 am – 12:30 pm","note":""},{"id":"d4","season":"Winter","session":"Evening","time":"6:00 pm – 8:30 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest Indian clothing is preferred; shoes off outside."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Darshan windows are shorter than at bigger temples — plan this one first in the morning."},{"id":"t2","text":"Photography is usually not allowed inside."}],"goodToKnow":"","address":{"street":"","locality":"Vrindavan","city":"Vrindavan","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Shri Radha Raman Temple Vrindavan","latitude":"","longitude":"","routes":[{"id":"r1","from":"Mathura","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days. A private car is the most comfortable choice."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"About 3 to 3.5 hours on the Yamuna Expressway in normal traffic, or a train to Mathura Junction and a 25 to 30 minute drive."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km to Mathura","how":"Around 1 to 1.5 hours to Mathura by road, then on to Vrindavan."},{"id":"r4","from":"Within Vrindavan","distance":"Short hops","how":"Cars cannot enter the narrow old-town lanes, so walk or take an e-rickshaw for the last stretch. Agree the fare before you sit."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"radha-vallabh"},{"id":"l2","slug":"seva-kunj"},{"id":"l3","slug":"madan-mohan"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Shri Radha Vallabh Temple', 'Vrindavan', 'radha-vallabh', '{"title":"Shri Radha Vallabh Temple, Vrindavan: Timings & Guide","description":"The temple of the Radha Vallabh sampradaya, where Radha is worshipped through a crown beside Krishna. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Shri Radha Vallabh Temple","description":"The temple of the Radha Vallabh sampradaya, where Radha is worshipped through a crown beside Krishna."}'::jsonb, 'photo:radha-vallabh', 'Devotees seated before the decorated altar at Radha Vallabh Temple, Vrindavan', 'The temple of the Radha Vallabh sampradaya, where Radha is worshipped through a crown beside Krishna.', '', 'Radha Vallabh ji was established in Vrindavan in the 16th century by Shri Hit Harivansh Mahaprabhu, founder of the Radha Vallabh tradition. In this tradition there is no separate murti of Radha; instead she is represented by a crown placed beside Krishna, emphasising their oneness.

The old red-sandstone temple dates from the Mughal era, and the newer temple beside it continues daily seva with rich samaj gayan — the singing of devotional poetry.', '<p>One older list gives 5:00 am – 12:00 noon and 6:00 – 9:00 pm.</p>', '', '', '', '<p>Shri Radha Vallabh Temple is in Vrindavan. The temple of the Radha Vallabh sampradaya, where Radha is worshipped through a crown beside Krishna. Usual darshan hours: morning 7:00 am – 12:00 noon, evening 6:30 pm – 9:00 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"श्री राधा वल्लभ मंदिर"},{"id":"g2","label":"Location","value":"Vrindavan"},{"id":"g3","label":"Type","value":"Radha Krishna Temple"},{"id":"g4","label":"Darshan","value":"Morning & evening darshan"},{"id":"g5","label":"Dress code","value":"Modest clothing; shoes left outside."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q2","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Radha Krishna Temple","featured":false,"sortOrder":"7","timingNote":"Morning & evening darshan","stats":[],"darshan":[{"id":"d1","season":"","session":"Morning","time":"7:00 am – 12:00 noon","note":""},{"id":"d2","season":"","session":"Evening","time":"6:30 pm – 9:00 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; shoes left outside."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Evening samaj gayan is a lovely, lesser-known experience."},{"id":"t2","text":"Very close to Seva Kunj and Banke Bihari."}],"goodToKnow":"","address":{"street":"","locality":"Vrindavan","city":"Vrindavan","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Shri Radha Vallabh Temple Vrindavan","latitude":"","longitude":"","routes":[{"id":"r1","from":"Mathura","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days. A private car is the most comfortable choice."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"About 3 to 3.5 hours on the Yamuna Expressway in normal traffic, or a train to Mathura Junction and a 25 to 30 minute drive."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km to Mathura","how":"Around 1 to 1.5 hours to Mathura by road, then on to Vrindavan."},{"id":"r4","from":"Within Vrindavan","distance":"Short hops","how":"Cars cannot enter the narrow old-town lanes, so walk or take an e-rickshaw for the last stretch. Agree the fare before you sit."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"seva-kunj"},{"id":"l2","slug":"banke-bihari"},{"id":"l3","slug":"radha-raman"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Govind Dev Ji Temple', 'Vrindavan', 'govind-dev-ji', '{"title":"Govind Dev Ji Temple, Vrindavan: Timings & Guide","description":"A monumental red-sandstone temple from 1590 — one of the finest pieces of temple architecture in North India. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Govind Dev Ji Temple","description":"A monumental red-sandstone temple from 1590 — one of the finest pieces of temple architecture in North India."}'::jsonb, 'photo:govind-dev', 'Red sandstone facade of the 16th-century Govind Dev Ji Temple in Vrindavan', 'A monumental red-sandstone temple from 1590 — one of the finest pieces of temple architecture in North India.', '', 'Built in 1590 by Raja Man Singh of Amber for the deity discovered by Rupa Goswami, Govind Dev Ji was once one of the largest temples in North India, said to have risen seven storeys. Its upper levels were lost during the late 17th century, and the original deity was taken to safety — today it is worshipped in Jaipur.

What remains is a cathedral-like hall of red sandstone with a vaulted ceiling, a striking blend of Hindu and Mughal-era building styles. A replica deity continues to be worshipped here.', '', '', '', '', '<p>Govind Dev Ji Temple is in Vrindavan. A monumental red-sandstone temple from 1590 — one of the finest pieces of temple architecture in North India. Usual darshan hours in summer: morning 8:00 am – 11:00 am, evening 5:00 pm – 8:30 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"श्री गोविंद देव जी मंदिर"},{"id":"g2","label":"Location","value":"Vrindavan"},{"id":"g3","label":"Type","value":"Goswami Temple"},{"id":"g4","label":"Darshan","value":"Morning & evening darshan"},{"id":"g5","label":"Dress code","value":"Modest clothing; shoes off outside the hall."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What are the seven Goswami temples of Vrindavan?","answer":"Govind Dev, Gopinath, Madan Mohan, Radha Raman, Radha Damodar, Radha Shyamsundar and Radha Gokulananda, established by the followers of Chaitanya Mahaprabhu. Some lists include Banke Bihari and Radha Vallabh as separately important temples."},{"id":"q2","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q3","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Goswami Temple","featured":false,"sortOrder":"8","timingNote":"Morning & evening darshan","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Morning","time":"8:00 am – 11:00 am","note":""},{"id":"d2","season":"Summer","session":"Evening","time":"5:00 pm – 8:30 pm","note":""},{"id":"d3","season":"Winter","session":"Morning","time":"9:00 am – 11:30 am","note":""},{"id":"d4","season":"Winter","session":"Evening","time":"5:00 pm – 8:30 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; shoes off outside the hall."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Bring a wide-angle view in mind — the interior is best appreciated by standing back."},{"id":"t2","text":"Usually less crowded than temples in the Banke Bihari lanes."}],"goodToKnow":"","address":{"street":"","locality":"Vrindavan","city":"Vrindavan","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Govind Dev Ji Temple Vrindavan","latitude":"","longitude":"","routes":[{"id":"r1","from":"Mathura","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days. A private car is the most comfortable choice."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"About 3 to 3.5 hours on the Yamuna Expressway in normal traffic, or a train to Mathura Junction and a 25 to 30 minute drive."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km to Mathura","how":"Around 1 to 1.5 hours to Mathura by road, then on to Vrindavan."},{"id":"r4","from":"Within Vrindavan","distance":"Short hops","how":"Cars cannot enter the narrow old-town lanes, so walk or take an e-rickshaw for the last stretch. Agree the fare before you sit."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"rangji"},{"id":"l2","slug":"madan-mohan"},{"id":"l3","slug":"radha-raman"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Shri Radha Madan Mohan Temple', 'Vrindavan', 'madan-mohan', '{"title":"Shri Radha Madan Mohan Temple, Vrindavan: Timings & Guide","description":"Vrindavan’s oldest surviving temple, rising above the old bank of the Yamuna near Kali Ghat. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Shri Radha Madan Mohan Temple","description":"Vrindavan’s oldest surviving temple, rising above the old bank of the Yamuna near Kali Ghat."}'::jsonb, 'photo:madan-mohan', 'Red sandstone spire of Madan Mohan Temple on a hillock in Vrindavan', 'Vrindavan’s oldest surviving temple, rising above the old bank of the Yamuna near Kali Ghat.', '', 'The tall, tapering spire of Madan Mohan temple stands on Dwadashaditya Tila, a small hill near Kali Ghat. The temple was established for the deity worshipped by Sanatana Goswami in the 16th century, and is considered the oldest surviving temple in Vrindavan.

The original deity was later moved to Karauli in Rajasthan for safety, and a pratibhu (representative) deity is worshipped here. The hill offers a peaceful view over the old town.', '', '', '', '', '<p>Shri Radha Madan Mohan Temple is in Vrindavan. Vrindavan’s oldest surviving temple, rising above the old bank of the Yamuna near Kali Ghat. Usual darshan hours in most of the year: morning 7:00 am – 12:00 noon, evening 5:00 pm – 8:00 pm.</p>', '[{"id":"g1","label":"Location","value":"Vrindavan, Uttar Pradesh"},{"id":"g2","label":"Type","value":"Goswami Temple"},{"id":"g3","label":"Darshan","value":"Morning & evening darshan"},{"id":"g4","label":"Dress code","value":"Modest clothing; shoes off at the steps."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What are the seven Goswami temples of Vrindavan?","answer":"Govind Dev, Gopinath, Madan Mohan, Radha Raman, Radha Damodar, Radha Shyamsundar and Radha Gokulananda, established by the followers of Chaitanya Mahaprabhu. Some lists include Banke Bihari and Radha Vallabh as separately important temples."},{"id":"q2","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q3","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Goswami Temple","featured":false,"sortOrder":"9","timingNote":"Morning & evening darshan","stats":[],"darshan":[{"id":"d1","season":"Most of the year","session":"Morning","time":"7:00 am – 12:00 noon","note":""},{"id":"d2","season":"Most of the year","session":"Evening","time":"5:00 pm – 8:00 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; shoes off at the steps."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"A short climb of steps — manageable for most seniors at an easy pace."},{"id":"t2","text":"Sunset from the hill is lovely in winter."}],"goodToKnow":"","address":{"street":"","locality":"Vrindavan","city":"Vrindavan","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Radha Madan Mohan Temple Vrindavan","latitude":"","longitude":"","routes":[{"id":"r1","from":"Mathura","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days. A private car is the most comfortable choice."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"About 3 to 3.5 hours on the Yamuna Expressway in normal traffic, or a train to Mathura Junction and a 25 to 30 minute drive."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km to Mathura","how":"Around 1 to 1.5 hours to Mathura by road, then on to Vrindavan."},{"id":"r4","from":"Within Vrindavan","distance":"Short hops","how":"Cars cannot enter the narrow old-town lanes, so walk or take an e-rickshaw for the last stretch. Agree the fare before you sit."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"radha-raman"},{"id":"l2","slug":"govind-dev-ji"},{"id":"l3","slug":"nidhivan"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Shri Rangji Temple', 'Vrindavan', 'rangji', '{"title":"Shri Rangji Temple, Vrindavan: Timings & Guide","description":"A grand South Indian-style temple to Shri Ranganath, with a towering gopuram and golden flag pillar. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Shri Rangji Temple","description":"A grand South Indian-style temple to Shri Ranganath, with a towering gopuram and golden flag pillar."}'::jsonb, 'photo:rangji', 'Tall white gopuram gateway of Shri Rangji Temple in Vrindavan', 'A grand South Indian-style temple to Shri Ranganath, with a towering gopuram and golden flag pillar.', '', 'Rangji Mandir was built in the mid-19th century by the Seth family of Mathura in the Dravidian style, with high gopuram gateways, a sacred tank and a tall gold-plated dhvaja stambha. It is dedicated to Shri Ranganath, a form of Vishnu, worshipped here in the tradition of the Sri Vaishnava saints.

Its annual Brahmotsav in spring, with a grand wooden chariot procession, is one of Vrindavan’s most colourful festivals.', '', '', '', '<p><strong>What it is known for.</strong> Rangji Mandir looks different from every other temple in town. Built in the mid-nineteenth century in the <strong>South Indian Dravidian style</strong>, it has a tall gopuram, a vast courtyard and a metal-plated flagstaff. It is dedicated to <strong>Lord Ranganatha</strong>, Vishnu reclining on the serpent Shesha, in the Sri Vaishnava tradition.</p>', '<p>Shri Rangji Temple is in Vrindavan. A grand South Indian-style temple to Shri Ranganath, with a towering gopuram and golden flag pillar. Usual darshan hours in summer: morning 5:30 am – 10:30 am, evening 4:00 pm – 9:00 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"श्री रंगजी मंदिर"},{"id":"g2","label":"Location","value":"Vrindavan"},{"id":"g3","label":"Type","value":"Vishnu Temple"},{"id":"g4","label":"Darshan","value":"Morning & evening darshan"},{"id":"g5","label":"Dress code","value":"Modest clothing; leather items may be restricted inside — ask at the gate."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q2","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Vishnu Temple","featured":false,"sortOrder":"10","timingNote":"Morning & evening darshan","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Morning","time":"5:30 am – 10:30 am","note":""},{"id":"d2","season":"Summer","session":"Evening","time":"4:00 pm – 9:00 pm","note":""},{"id":"d3","season":"Winter","session":"Morning","time":"6:00 am – 11:00 am","note":""},{"id":"d4","season":"Winter","session":"Evening","time":"4:00 pm – 9:00 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; leather items may be restricted inside — ask at the gate."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"I bring guests here because it shows how wide Vrindavan''s devotion is. In a few kilometres you move from the playful child Krishna to the majestic Vishnu of the South. The annual Brahmotsav in spring brings grand processions."},{"id":"t2","text":"Photography rules differ in the outer and inner courtyards."},{"id":"t3","text":"Close to Govind Dev Ji — see both in an hour."}],"goodToKnow":"","address":{"street":"","locality":"Vrindavan","city":"Vrindavan","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Shri Rangji Mandir Vrindavan","latitude":"","longitude":"","routes":[{"id":"r1","from":"Mathura","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days. A private car is the most comfortable choice."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"About 3 to 3.5 hours on the Yamuna Expressway in normal traffic, or a train to Mathura Junction and a 25 to 30 minute drive."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km to Mathura","how":"Around 1 to 1.5 hours to Mathura by road, then on to Vrindavan."},{"id":"r4","from":"Within Vrindavan","distance":"Short hops","how":"Cars cannot enter the narrow old-town lanes, so walk or take an e-rickshaw for the last stretch. Agree the fare before you sit."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"govind-dev-ji"},{"id":"l2","slug":"iskcon-krishna-balaram"},{"id":"l3","slug":"prem-mandir"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Shri Krishna Janmabhoomi', 'Mathura', 'krishna-janmabhoomi', '{"title":"Shri Krishna Janmabhoomi, Mathura: Timings & Guide","description":"The sacred birthplace of Shri Krishna in Mathura, with the prison-cell shrine and Bhagavata Bhavan. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Shri Krishna Janmabhoomi","description":"The sacred birthplace of Shri Krishna in Mathura, with the prison-cell shrine and Bhagavata Bhavan."}'::jsonb, 'photo:janmabhoomi', 'Pink sandstone temple at the Shri Krishna Janmabhoomi complex in Mathura', 'The sacred birthplace of Shri Krishna in Mathura, with the prison-cell shrine and Bhagavata Bhavan.', '', 'According to tradition, Shri Krishna was born to Devaki and Vasudeva in a prison cell of King Kamsa at this spot in Mathura. The complex today includes the Garbha Griha — a small shrine marking the birthplace — the Keshav Dev temple and the large Bhagavata Bhavan with its painted ceilings.

Janmashtami here is one of the great celebrations of India, culminating in the midnight abhishek of the Lord.', '<p>Phones, cameras and bags are not allowed inside; lockers are near the entrance.</p>', '', '', '<p><strong>Shri Krishna Janmabhoomi Mathura</strong> marks the place where Krishna is believed to have been born to Devaki and Vasudeva in Kamsa''s prison. The site is also known as Katra Keshav Dev, and over the centuries successive temples stood on or near this ground. Today the complex includes the <strong>Garbha Griha</strong> (the prison-cell shrine), the <strong>Keshav Dev Temple</strong> and the Bhagavat Bhavan, with gardens and smaller shrines.</p><p><strong>Security rules and lockers.</strong> The complex has strict security checks. Mobile phones, cameras, bags, electronics and often even small items are not allowed inside. There are cloakroom and locker facilities outside the entrance. Carry only what you truly need.</p>', '<p>Shri Krishna Janmabhoomi is in Mathura. The sacred birthplace of Shri Krishna in Mathura, with the prison-cell shrine and Bhagavata Bhavan. Usual darshan hours in summer: morning 5:00 am – 12:00 noon, evening 4:00 pm – 9:30 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"श्री कृष्ण जन्मभूमि"},{"id":"g2","label":"Location","value":"Mathura"},{"id":"g3","label":"Type","value":"Radha Krishna Temple"},{"id":"g4","label":"Darshan","value":"Long morning & evening hours; strict security"},{"id":"g5","label":"Dress code","value":"Modest clothing; expect a security frisking."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"Which temple should I visit first in Mathura?","answer":"Begin at Vishram Ghat at sunrise, as pilgrims have traditionally done, and then go to Shri Krishna Janmabhoomi when it opens, when the security queue is shortest."},{"id":"q2","question":"Are phones allowed inside Mathura Vrindavan temples?","answer":"In many major temples, including Krishna Janmabhoomi and often Banke Bihari and Prem Mandir''s inner sanctum, mobile phones, cameras and bags are restricted. Lockers or cloakrooms are usually available nearby. Rules can change, so check on the day, or leave valuables in your vehicle or hotel."},{"id":"q3","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q4","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Radha Krishna Temple","featured":true,"sortOrder":"11","timingNote":"Long morning & evening hours; strict security","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Morning","time":"5:00 am – 12:00 noon","note":""},{"id":"d2","season":"Summer","session":"Evening","time":"4:00 pm – 9:30 pm","note":""},{"id":"d3","season":"Winter","session":"Morning","time":"5:30 am – 12:00 noon","note":""},{"id":"d4","season":"Winter","session":"Evening","time":"3:00 pm – 8:30 pm","note":""}],"aarti":[{"id":"a1","season":"Summer","name":"Darshan opens","time":"5:00 am"},{"id":"a2","season":"Summer","name":"Mangla aarti","time":"5:30 am"},{"id":"a3","season":"Summer","name":"Makhan bhog","time":"8:00 am"},{"id":"a4","season":"Summer","name":"Morning darshan closes","time":"12:00 noon"},{"id":"a5","season":"Summer","name":"Evening darshan opens","time":"4:00 pm"},{"id":"a6","season":"Summer","name":"Sandhya aarti","time":"6:00 pm"},{"id":"a7","season":"Summer","name":"Darshan closes","time":"9:30 pm"},{"id":"a8","season":"Winter","name":"Darshan opens · mangla aarti","time":"5:30 am"},{"id":"a9","season":"Winter","name":"Makhan bhog","time":"8:00 am"},{"id":"a10","season":"Winter","name":"Morning darshan closes","time":"12:00 noon"},{"id":"a11","season":"Winter","name":"Evening darshan opens","time":"3:00 pm"},{"id":"a12","season":"Winter","name":"Sandhya aarti","time":"6:00 pm"},{"id":"a13","season":"Winter","name":"Darshan closes","time":"8:30 pm"}],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; expect a security frisking."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"The entry gate and queue arrangement are decided by the authorities and can change, so I always check on the day which entrance is in use, and I walk my guests to the correct one, away from touts. Please do not hand your phone to strangers in the lane who offer to \"keep it safe.\" Use the official counter. Come early for shorter security queues. And once you reach the Garbha Griha, do not rush. Stand still for a few moments and let the weight of the place settle. For many of my guests this is the most emotional minute of the whole trip. During Janmashtami, queues can run for hours, so book well ahead."},{"id":"t2","text":"Carry as little as possible to move through security quickly."},{"id":"t3","text":"Allow 60–90 minutes for the full complex."},{"id":"t4","text":"On Janmashtami the queues can stretch for hours — plan with us well ahead."}],"goodToKnow":"Phones, cameras, bags, belts and many electronic items are not permitted inside. Lockers are available near the entrance, or leave items in the car.","address":{"street":"","locality":"Mathura","city":"Mathura","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Shri Krishna Janmabhoomi Mathura","latitude":"","longitude":"","routes":[{"id":"r1","from":"Vrindavan","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"Frequent express trains reach Mathura Junction (MTJ) in about 2 to 3 hours, or drive the Yamuna Expressway in about 3 to 3.5 hours."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km","how":"Around 1 to 1.5 hours by road. Trains from Agra Cantt are frequent and quick."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"dwarkadhish"},{"id":"l2","slug":"vishram-ghat"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Dwarkadhish Temple', 'Mathura', 'dwarkadhish', '{"title":"Dwarkadhish Temple, Mathura: Timings & Guide","description":"An ornate 19th-century haveli temple in old Mathura, famed for its monsoon jhula festival. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Dwarkadhish Temple","description":"An ornate 19th-century haveli temple in old Mathura, famed for its monsoon jhula festival."}'::jsonb, 'photo:dwarkadhish', 'Painted courtyard and carved balconies of Dwarkadhish Temple, Mathura', 'An ornate 19th-century haveli temple in old Mathura, famed for its monsoon jhula festival.', '', 'The Dwarkadhish temple was built in 1814 by Seth Gokul Das Parikh, treasurer of the Gwalior state, in the style of a grand Rajasthani haveli. Worship follows the Pushti Marg tradition, where darshan opens for short periods through the day, timed to the Lord’s daily routine.

In the monsoon month of Shravan (July–August), the temple is famous for its jhula (swing) festival, when Thakur ji is placed on swings of gold, silver and flowers.', '<p>Worship follows the Pushti Marg tradition: the doors open only for these short jhankis. No winter Shayan time is published.</p>', '', '', '<p>Built in the early nineteenth century (1814), the Dwarkadhish Temple is a beautiful haveli-style temple with carved pillars, painted ceilings and <strong>Rajasthani architecture</strong>. It follows the Pushtimarg tradition, in which the deity is cared for like a beloved child with seasonal dress and carefully planned offerings. It is especially colourful during <strong>Holi, Jhulan Yatra and Hindola</strong>.</p>', '<p>Dwarkadhish Temple is in Mathura. An ornate 19th-century haveli temple in old Mathura, famed for its monsoon jhula festival. Usual darshan hours in summer: morning 6:30 am – 10:30 am, evening 4:00 pm – 7:00 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"द्वारकाधीश मंदिर"},{"id":"g2","label":"Location","value":"Mathura"},{"id":"g3","label":"Type","value":"Radha Krishna Temple"},{"id":"g4","label":"Darshan","value":"Short darshan windows; closed midday"},{"id":"g5","label":"Dress code","value":"Modest clothing; shoes off outside."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q2","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Radha Krishna Temple","featured":false,"sortOrder":"12","timingNote":"Short darshan windows; closed midday","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Morning","time":"6:30 am – 10:30 am","note":""},{"id":"d2","season":"Summer","session":"Evening","time":"4:00 pm – 7:00 pm","note":""},{"id":"d3","season":"Winter","session":"Morning","time":"6:30 am – 10:30 am","note":""},{"id":"d4","season":"Winter","session":"Evening","time":"3:30 pm – 6:00 pm","note":"Last listed aarti 6:00 pm"}],"aarti":[{"id":"a1","season":"Summer","name":"Mangla","time":"6:30 – 7:00 am"},{"id":"a2","season":"Summer","name":"Shringar","time":"7:40 – 7:55 am"},{"id":"a3","season":"Summer","name":"Gwal","time":"8:25 – 8:45 am"},{"id":"a4","season":"Summer","name":"Rajbhog","time":"10:00 – 10:30 am"},{"id":"a5","season":"Summer","name":"Utthapan","time":"4:00 – 4:20 pm"},{"id":"a6","season":"Summer","name":"Bhog","time":"4:45 – 5:05 pm"},{"id":"a7","season":"Summer","name":"Aarti","time":"5:20 – 5:40 pm"},{"id":"a8","season":"Summer","name":"Shayan","time":"6:30 – 7:00 pm"},{"id":"a9","season":"Winter","name":"Mangla","time":"6:30 – 7:00 am"},{"id":"a10","season":"Winter","name":"Shringar","time":"7:40 – 7:55 am"},{"id":"a11","season":"Winter","name":"Gwal","time":"8:25 – 8:45 am"},{"id":"a12","season":"Winter","name":"Rajbhog","time":"10:00 – 10:30 am"},{"id":"a13","season":"Winter","name":"Utthapan","time":"3:30 – 3:50 pm"},{"id":"a14","season":"Winter","name":"Bhog","time":"4:45 – 5:05 pm"},{"id":"a15","season":"Winter","name":"Aarti","time":"6:00 pm"}],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; shoes off outside."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"The temple is close to the Yamuna ghats, so I combine it with Vishram Ghat. Start at the ghat at sunrise, walk the short distance to Dwarkadhish and finish before the main rush. The temple''s sweets and prasad are excellent, but buy from the official counters."},{"id":"t2","text":"Darshan opens in short slots, so we time this visit carefully on Mathura days."},{"id":"t3","text":"Walk down to Vishram Ghat afterwards — it is only a few minutes away."}],"goodToKnow":"","address":{"street":"","locality":"Mathura","city":"Mathura","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Dwarkadhish Temple Mathura","latitude":"","longitude":"","routes":[{"id":"r1","from":"Vrindavan","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"Frequent express trains reach Mathura Junction (MTJ) in about 2 to 3 hours, or drive the Yamuna Expressway in about 3 to 3.5 hours."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km","how":"Around 1 to 1.5 hours by road. Trains from Agra Cantt are frequent and quick."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"vishram-ghat"},{"id":"l2","slug":"krishna-janmabhoomi"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Vishram Ghat', 'Mathura', 'vishram-ghat', '{"title":"Vishram Ghat, Mathura: Timings & Guide","description":"Mathura’s principal ghat, where Krishna rested after defeating Kamsa — and home to the evening Yamuna aarti. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Vishram Ghat","description":"Mathura’s principal ghat, where Krishna rested after defeating Kamsa — and home to the evening Yamuna aarti."}'::jsonb, 'photo:vishram-ghat', 'Boats and lit temples along Vishram Ghat on the Yamuna in Mathura at dusk', 'Mathura’s principal ghat, where Krishna rested after defeating Kamsa — and home to the evening Yamuna aarti.', '', 'Vishram means rest: tradition says that Shri Krishna rested at this spot on the Yamuna after defeating King Kamsa. It is the central ghat among the many that line Mathura’s riverfront and is the traditional start and end point of the Braj parikrama.

Every evening, priests perform the Yamuna aarti with large brass lamps while devotees float leaf-cup diyas on the water.', '<p>The ghat itself is open all day.</p><p>Another published list gives 4:45 am and 7:30 pm. The evening aarti generally follows sunset.</p><p>Reach 20–30 minutes early for a place on the steps, or watch from a boat.</p>', '', '', '', '<p>Vishram Ghat is in Mathura. Mathura’s principal ghat, where Krishna rested after defeating Kamsa — and home to the evening Yamuna aarti. Usual darshan hours in summer: morning 7:00 am – 7:15 am, evening 6:45 pm – 7:00 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"विश्राम घाट"},{"id":"g2","label":"Location","value":"Mathura"},{"id":"g3","label":"Type","value":"Ghat & Kund"},{"id":"g4","label":"Darshan","value":"Open all day; aarti around sunset"},{"id":"g5","label":"Dress code","value":"Modest clothing; the steps can be slippery — wear easy footwear until you reach the water."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"Which temple should I visit first in Mathura?","answer":"Begin at Vishram Ghat at sunrise, as pilgrims have traditionally done, and then go to Shri Krishna Janmabhoomi when it opens, when the security queue is shortest."},{"id":"q2","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q3","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Ghat & Kund","featured":false,"sortOrder":"13","timingNote":"Open all day; aarti around sunset","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Morning","time":"7:00 am – 7:15 am","note":""},{"id":"d2","season":"Summer","session":"Evening","time":"6:45 pm – 7:00 pm","note":""},{"id":"d3","season":"Winter","session":"Morning","time":"6:45 am – 7:00 am","note":""},{"id":"d4","season":"Winter","session":"Evening","time":"6:45 pm – 7:00 pm","note":""}],"aarti":[{"id":"a1","season":"Summer","name":"Morning Yamuna aarti","time":"7:00 – 7:15 am"},{"id":"a2","season":"Summer","name":"Evening Yamuna aarti","time":"6:45 – 7:00 pm"},{"id":"a3","season":"Winter","name":"Morning Yamuna aarti","time":"6:45 – 7:00 am"},{"id":"a4","season":"Winter","name":"Evening Yamuna aarti","time":"6:45 – 7:00 pm"}],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; the steps can be slippery — wear easy footwear until you reach the water."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Reach 20–30 minutes before aarti to find a good spot on the steps."},{"id":"t2","text":"A short boat ride at dusk gives the best view of the aarti."},{"id":"t3","text":"Agree boat fares before boarding."}],"goodToKnow":"","address":{"street":"","locality":"Mathura","city":"Mathura","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Vishram Ghat Mathura","latitude":"","longitude":"","routes":[{"id":"r1","from":"Vrindavan","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"Frequent express trains reach Mathura Junction (MTJ) in about 2 to 3 hours, or drive the Yamuna Expressway in about 3 to 3.5 hours."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km","how":"Around 1 to 1.5 hours by road. Trains from Agra Cantt are frequent and quick."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"dwarkadhish"},{"id":"l2","slug":"krishna-janmabhoomi"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Shri Radha Rani Temple (Shriji Mandir)', 'Barsana', 'radha-rani-temple-barsana', '{"title":"Shri Radha Rani Temple (Shriji Mandir), Barsana: Timings & G","description":"The hilltop palace-temple of Shri Radha in Barsana, centre of the famous Lathmar Holi. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Shri Radha Rani Temple (Shriji Mandir)","description":"The hilltop palace-temple of Shri Radha in Barsana, centre of the famous Lathmar Holi."}'::jsonb, 'photo:radha-rani-barsana', 'Devotees in the courtyard of Shri Radha Rani Temple, Barsana', 'The hilltop palace-temple of Shri Radha in Barsana, centre of the famous Lathmar Holi.', '', 'Barsana is revered as the home of Shri Radha, daughter of King Vrishabhanu. The Shriji or Ladli ji temple crowns Bhanugarh hill, its red sandstone arches and domes visible from across the plain.

Each spring, Barsana and neighbouring Nandgaon celebrate Lathmar Holi — a playful re-enactment of Krishna and his friends teasing the gopis, who chase them away with sticks.', '', '', '', '<p>Barsana is Radha''s village, and the <strong>Radha Rani Temple (Ladli Ji)</strong> sits on the hilltop of Bhanugarh. You climb a long flight of steps, a couple of hundred, to reach it. The climb is part of the experience, with devotees singing, children racing ahead and old women resting at the landings.</p><p>Barsana is also the home of <strong>Lathmar Holi</strong>, when women playfully strike visiting men with sticks in a celebration that is more joyful than rough. Other sites here include <strong>Maan Mandir</strong> and <strong>Kirti Mandir</strong>, a rare temple dedicated to Radha''s mother.</p>', '<p>Shri Radha Rani Temple (Shriji Mandir) is in Barsana. The hilltop palace-temple of Shri Radha in Barsana, centre of the famous Lathmar Holi. Usual darshan hours: morning 5:00 am – 2:00 pm, evening 5:00 pm – 8:00 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"श्री राधा रानी मंदिर (श्रीजी)"},{"id":"g2","label":"Location","value":"Barsana"},{"id":"g3","label":"Type","value":"Radha Krishna Temple"},{"id":"g4","label":"Darshan","value":"Morning & evening darshan; steps or ropeway"},{"id":"g5","label":"Dress code","value":"Modest clothing; comfortable footwear for the steps (removed at the temple)."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q2","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Radha Krishna Temple","featured":true,"sortOrder":"14","timingNote":"Morning & evening darshan; steps or ropeway","stats":[],"darshan":[{"id":"d1","season":"","session":"Morning","time":"5:00 am – 2:00 pm","note":""},{"id":"d2","season":"","session":"Evening","time":"5:00 pm – 8:00 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; comfortable footwear for the steps (removed at the temple)."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Reach early and climb before the sun and the crowd build up. Seniors can ask about the options for reaching the top with help. During Holi and Radhashtami, stay overnight nearby and visit at opening time."},{"id":"t2","text":"Go early in the morning to climb before the heat."},{"id":"t3","text":"On Radhashtami and Holi the town fills to capacity — book transport early."},{"id":"t4","text":"Pair with Nandgaon, just 8 km away."}],"goodToKnow":"The temple is reached by a long flight of stone steps. A ropeway has operated in recent years — check whether it is running on your date.","address":{"street":"","locality":"Barsana","city":"Barsana","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Shri Radha Rani Temple Barsana","latitude":"","longitude":"","routes":[{"id":"r1","from":"Govardhan","distance":"About 25 km","how":"By road. A private car is the most comfortable way to travel between the towns of Braj."},{"id":"r2","from":"Nandgaon","distance":"About 8 km","how":"A short drive. Most pilgrims see both on the same day."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"nand-bhawan-nandgaon"},{"id":"l2","slug":"daan-ghati-govardhan"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Nand Bhawan, Nandgaon', 'Nandgaon', 'nand-bhawan-nandgaon', '{"title":"Nand Bhawan, Nandgaon, Nandgaon: Timings & Guide","description":"The hilltop home of Nanda Maharaj and Yashoda, where Krishna spent his childhood years. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Nand Bhawan, Nandgaon","description":"The hilltop home of Nanda Maharaj and Yashoda, where Krishna spent his childhood years."}'::jsonb, 'photo:nandgaon-holi', 'Crowds celebrating Holi with bright colours in Nandgaon', 'The hilltop home of Nanda Maharaj and Yashoda, where Krishna spent his childhood years.', '', 'Nandgaon sits on Nandishwar hill, a short drive from Barsana. Tradition says that Nanda Maharaj moved his family and herds here from Gokul, and that Krishna and Balaram grew up in this village.

The Nand Bhawan temple honours Nanda, Yashoda, Krishna and Balaram together. The day after Barsana’s Lathmar Holi, the women of Nandgaon host their own celebration for the men of Barsana.', '', '', '', '<p>Nandgaon is where Krishna was raised by Nanda Baba and Yashoda. The <strong>Nand Bhavan</strong> (Nand Mahal) temple sits on a hillock and is reached by steps, with views over the village. During Holi, Nandgaon celebrates the day after Barsana, when the men of Nandgaon visit Barsana and the playful tradition continues.</p>', '<p>Nand Bhawan, Nandgaon is in Nandgaon. The hilltop home of Nanda Maharaj and Yashoda, where Krishna spent his childhood years. Usual darshan hours: morning 7:00 am – 1:00 pm, evening 3:00 pm – 9:00 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"नंद बाबा मंदिर (नंद भवन)"},{"id":"g2","label":"Location","value":"Nandgaon"},{"id":"g3","label":"Type","value":"Radha Krishna Temple"},{"id":"g4","label":"Darshan","value":"Morning & evening darshan"},{"id":"g5","label":"Dress code","value":"Modest clothing; shoes off at the temple."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q2","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Radha Krishna Temple","featured":false,"sortOrder":"15","timingNote":"Morning & evening darshan","stats":[],"darshan":[{"id":"d1","season":"","session":"Morning","time":"7:00 am – 1:00 pm","note":""},{"id":"d2","season":"","session":"Evening","time":"3:00 pm – 9:00 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; shoes off at the temple."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Combine Nandgaon with Barsana on the same day, since they are close, and keep your phone safe during festival days."},{"id":"t2","text":"Vehicles can get close to the top; a short climb remains."},{"id":"t3","text":"Visit together with Barsana on the same day."}],"goodToKnow":"","address":{"street":"","locality":"Nandgaon","city":"Nandgaon","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Nand Bhawan Nandgaon","latitude":"","longitude":"","routes":[{"id":"r1","from":"Barsana","distance":"About 8 km","how":"A short drive. Most pilgrims see both on the same day."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"radha-rani-temple-barsana"},{"id":"l2","slug":"daan-ghati-govardhan"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Daan Ghati Temple, Govardhan', 'Govardhan', 'daan-ghati-govardhan', '{"title":"Daan Ghati Temple, Govardhan, Govardhan: Timings & Guide","description":"The Giriraj ji temple where most pilgrims begin the 21 km Govardhan Parikrama. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Daan Ghati Temple, Govardhan","description":"The Giriraj ji temple where most pilgrims begin the 21 km Govardhan Parikrama."}'::jsonb, 'photo:daan-ghati', 'Temple pavilion with a sculpted Govardhan hill at Daan Ghati, Govardhan', 'The Giriraj ji temple where most pilgrims begin the 21 km Govardhan Parikrama.', '', 'Govardhan hill — Giriraj ji — is worshipped as a form of Krishna himself, who lifted it on his finger to shelter the people of Braj from Indra’s storms. The Daan Ghati temple stands where the main road crosses the hill and is the most common starting point for parikrama.

Devotees offer milk abhishek to the sacred stone of Giriraj ji here before setting out.', '', '', '', '<p>Govardhan is the sacred hill Krishna lifted on his little finger to shelter the villagers from Indra''s rain. The <strong>Govardhan Parikrama</strong> is a walk of about <strong>21 km</strong> around the hill, and devotees consider it among the most rewarding acts in Braj.</p><p>Key stops include <strong>Daan Ghati</strong>, the Giriraj temple where tradition says Krishna collected a playful toll from the gopis, as well as <strong>Mansi Ganga</strong>, <strong>Haridev Temple</strong>, <strong>Kusum Sarovar</strong> and <strong>Radha Kund and Shyam Kund</strong>, two of the holiest water bodies in Braj.</p>', '<p>Daan Ghati Temple, Govardhan is in Govardhan. The Giriraj ji temple where most pilgrims begin the 21 km Govardhan Parikrama. Usual darshan hours in summer: open 6:00 am – 9:00 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"दानघाटी मंदिर"},{"id":"g2","label":"Location","value":"Govardhan"},{"id":"g3","label":"Type","value":"Sacred Hill"},{"id":"g4","label":"Darshan","value":"Open from early morning; busiest on Purnima"},{"id":"g5","label":"Dress code","value":"Modest clothing. Many devotees walk the parikrama barefoot."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"Is the Govardhan Parikrama difficult?","answer":"It is about 21 km. Many devotees walk barefoot, but you can walk part of it or use vehicle support between key stops. Winter dawn is the most comfortable time."},{"id":"q2","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q3","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Sacred Hill","featured":false,"sortOrder":"16","timingNote":"Open from early morning; busiest on Purnima","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Open","time":"6:00 am – 9:00 pm","note":""},{"id":"d2","season":"Winter","session":"Open","time":"7:00 am – 9:00 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing. Many devotees walk the parikrama barefoot."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Walk in winter at dawn, when the air is cool. In summer, start before sunrise or do it with vehicle support. We arrange stage-by-stage help for those who cannot walk the full distance. Carry water and keep your footwear handy for road stretches."},{"id":"t2","text":"Purnima (full moon) and Guru Purnima draw very large crowds."},{"id":"t3","text":"If walking the parikrama, start before dawn to avoid the heat."}],"goodToKnow":"","address":{"street":"","locality":"Govardhan","city":"Govardhan","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Daan Ghati Temple Govardhan","latitude":"","longitude":"","routes":[{"id":"r1","from":"Mathura","distance":"About 25 km","how":"By road. A private car makes it easy to combine with Barsana."},{"id":"r2","from":"Barsana","distance":"About 25 km","how":"By road."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"mukharvind-govardhan"},{"id":"l2","slug":"radha-rani-temple-barsana"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Mukharvind & Mansi Ganga, Govardhan', 'Govardhan', 'mukharvind-govardhan', '{"title":"Mukharvind & Mansi Ganga, Govardhan, Govardhan: Timings & Gu","description":"The ‘lotus face’ of Giriraj ji, worshipped beside the sacred lake of Mansi Ganga. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Mukharvind & Mansi Ganga, Govardhan","description":"The ‘lotus face’ of Giriraj ji, worshipped beside the sacred lake of Mansi Ganga."}'::jsonb, 'photo:mansi-ganga', 'Mansi Ganga lake in Govardhan with temples along its far bank', 'The ‘lotus face’ of Giriraj ji, worshipped beside the sacred lake of Mansi Ganga.', '', 'Mukharvind means ‘lotus face’. At the Mukharvind shrines — the best known at Mansi Ganga and at Jatipura — Giriraj ji is worshipped as the face of the Lord, and devotees offer milk, sweets and flowers.

Mansi Ganga, the large stepped lake at the centre of Govardhan town, is said to have been manifested from Krishna’s mind. It is lined with temples and old chhatris.', '', '', '', '', '<p>Mukharvind &amp; Mansi Ganga, Govardhan is in Govardhan. The ‘lotus face’ of Giriraj ji, worshipped beside the sacred lake of Mansi Ganga. Usual darshan hours in summer: morning 7:30 am – 12:30 pm, evening 4:30 pm – 8:30 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"मुखारविंद मंदिर"},{"id":"g2","label":"Location","value":"Govardhan"},{"id":"g3","label":"Type","value":"Sacred Hill"},{"id":"g4","label":"Darshan","value":"Open most of the day"},{"id":"g5","label":"Dress code","value":"Modest clothing; barefoot near the shrines."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"Is the Govardhan Parikrama difficult?","answer":"It is about 21 km. Many devotees walk barefoot, but you can walk part of it or use vehicle support between key stops. Winter dawn is the most comfortable time."},{"id":"q2","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q3","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Sacred Hill","featured":false,"sortOrder":"17","timingNote":"Open most of the day","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Morning","time":"7:30 am – 12:30 pm","note":""},{"id":"d2","season":"Summer","session":"Evening","time":"4:30 pm – 8:30 pm","note":""},{"id":"d3","season":"Winter","session":"Morning","time":"7:30 am – 12:30 pm","note":""},{"id":"d4","season":"Winter","session":"Evening","time":"4:00 pm – 8:30 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; barefoot near the shrines."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Evening deep daan on the lake during Kartik is especially beautiful."},{"id":"t2","text":"Easily reached by e-rickshaw from Daan Ghati."}],"goodToKnow":"","address":{"street":"","locality":"Govardhan","city":"Govardhan","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Mukharvind Mansi Ganga Govardhan","latitude":"","longitude":"","routes":[{"id":"r1","from":"Mathura","distance":"About 25 km","how":"By road. A private car makes it easy to combine with Barsana."},{"id":"r2","from":"Barsana","distance":"About 25 km","how":"By road."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"daan-ghati-govardhan"},{"id":"l2","slug":"radha-rani-temple-barsana"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Gokul & Raman Reti', 'Gokul', 'gokul', '{"title":"Gokul & Raman Reti, Gokul: Timings & Guide","description":"The riverside village where baby Krishna was raised by Yashoda — with Raman Reti and Brahmand Ghat nearby. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Gokul & Raman Reti","description":"The riverside village where baby Krishna was raised by Yashoda — with Raman Reti and Brahmand Ghat nearby."}'::jsonb, 'photo:gokul', 'A small temple gateway in the village of Gokul near Mathura', 'The riverside village where baby Krishna was raised by Yashoda — with Raman Reti and Brahmand Ghat nearby.', '', 'Across the Yamuna from Mathura lies Gokul, where Vasudeva carried the newborn Krishna to safety on the night of his birth. Here Krishna was raised by Nanda and Yashoda, and the village is full of shrines remembering his childhood pranks.

Nearby are Raman Reti, a sandy grove where devotees roll in the sand where the Lord played, and Brahmand Ghat, where Yashoda is said to have seen the whole universe in little Krishna’s mouth.', '<p>Another list gives 5:00 am – 12:00 noon and 4:00 – 8:30 pm.</p>', '', '', '<p>Gokul is where Krishna spent his infancy. <strong>Raman Reti</strong> is a stretch of soft, fine sand where the baby Krishna is said to have crawled and played. Pilgrims often roll or sit on it, touching the sand to their foreheads. <strong>Chaurasi Khamba</strong> (the 84-pillar hall), linked with Nanda Bhavan in Mahavan, is a quiet, atmospheric stop.</p><p>Gokul also has the <strong>Gokulnath Temple</strong> (an important Pushtimarg seat) and <strong>Brahmand Ghat</strong>, where Krishna is said to have shown Yashoda the universe inside his mouth.</p>', '<p>Gokul &amp; Raman Reti is in Mahavan, near Gokul. The riverside village where baby Krishna was raised by Yashoda — with Raman Reti and Brahmand Ghat nearby. Usual darshan hours: morning 4:00 am – 11:00 am, evening 4:30 pm – 8:30 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"रमण रेती आश्रम"},{"id":"g2","label":"Location","value":"Mahavan, near Gokul"},{"id":"g3","label":"Type","value":"Pilgrimage Town"},{"id":"g4","label":"Darshan","value":"Morning & evening darshan at most shrines"},{"id":"g5","label":"Dress code","value":"Modest clothing; shoes off at each shrine."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q2","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Pilgrimage Town","featured":false,"sortOrder":"18","timingNote":"Morning & evening darshan at most shrines","stats":[],"darshan":[{"id":"d1","season":"","session":"Morning","time":"4:00 am – 11:00 am","note":""},{"id":"d2","season":"","session":"Evening","time":"4:30 pm – 8:30 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; shoes off at each shrine."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Wear clothes you do not mind getting sandy at Raman Reti, and visit in the morning or late afternoon."},{"id":"t2","text":"Agree any priest or guide donation upfront."},{"id":"t3","text":"Combine with Dauji temple in Baldeo for a half-day circuit."}],"goodToKnow":"","address":{"street":"","locality":"Mahavan, near Gokul","city":"Gokul","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Gokul Mathura temple","latitude":"","longitude":"","routes":[{"id":"r1","from":"Vrindavan","distance":"About 20 km","how":"By road, usually combined with Mathura or Baldeo."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"dauji-baldeo"},{"id":"l2","slug":"vishram-ghat"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Shri Dauji Temple, Baldeo', 'Baldeo', 'dauji-baldeo', '{"title":"Shri Dauji Temple, Baldeo, Baldeo: Timings & Guide","description":"The temple of Balarama — Krishna’s elder brother — with his consort Revati, famous for the Huranga festival. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Shri Dauji Temple, Baldeo","description":"The temple of Balarama — Krishna’s elder brother — with his consort Revati, famous for the Huranga festival."}'::jsonb, 'photo:dauji', 'Devotional image of Dauji and Revati Maiya at the Baldeo temple', 'The temple of Balarama — Krishna’s elder brother — with his consort Revati, famous for the Huranga festival.', '', 'Baldeo, south-east of Mathura, is dedicated to Shri Balarama, lovingly called Dauji (elder brother). The temple houses a striking black stone deity of Dauji with Revati Maiya.

The day after Holi, Baldeo celebrates Huranga — a boisterous festival in which women playfully drench and tear the shirts of the men, who sing and dance in reply.', '', '', '', '', '<p>Shri Dauji Temple, Baldeo is in Baldeo. The temple of Balarama — Krishna’s elder brother — with his consort Revati, famous for the Huranga festival. Usual darshan hours in summer: morning 6:00 am – 11:00 am, evening 4:00 pm – 9:00 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"श्री दाऊजी मंदिर"},{"id":"g2","label":"Location","value":"Baldeo"},{"id":"g3","label":"Type","value":"Radha Krishna Temple"},{"id":"g4","label":"Darshan","value":"Morning & evening darshan"},{"id":"g5","label":"Dress code","value":"Modest clothing; shoes off at the gate."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q2","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Radha Krishna Temple","featured":false,"sortOrder":"19","timingNote":"Morning & evening darshan","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Morning","time":"6:00 am – 11:00 am","note":""},{"id":"d2","season":"Summer","session":"Evening","time":"4:00 pm – 9:00 pm","note":""},{"id":"d3","season":"Winter","session":"Morning","time":"7:00 am – 12:00 noon","note":""},{"id":"d4","season":"Winter","session":"Evening","time":"3:00 pm – 8:00 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing; shoes off at the gate."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Try the famous makhan-mishri offered around the temple."},{"id":"t2","text":"Huranga day is extremely crowded and wet — dress accordingly."}],"goodToKnow":"","address":{"street":"","locality":"Baldeo","city":"Baldeo","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Dauji Temple Baldeo","latitude":"","longitude":"","routes":[{"id":"r1","from":"Mathura","distance":"South-east of Mathura","how":"By road, usually combined with Gokul for a half-day circuit."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"gokul"},{"id":"l2","slug":"vishram-ghat"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Gita Mandir (Birla Mandir)', 'Mathura', 'gita-mandir', '{"title":"Gita Mandir (Birla Mandir), Mathura: Timings & Guide","description":"A calm red sandstone temple on the Mathura–Vrindavan road, with the Bhagavad Gita inscribed on its pillars. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Gita Mandir (Birla Mandir)","description":"A calm red sandstone temple on the Mathura–Vrindavan road, with the Bhagavad Gita inscribed on its pillars."}'::jsonb, '', '', 'A calm red sandstone temple on the Mathura–Vrindavan road, with the Bhagavad Gita inscribed on its pillars.', '', '', '<p>One list gives a 5:00 am winter opening.</p>', '', '', '<p>Built by the Birla family and completed in the mid-twentieth century (1946), this red sandstone temple is also known as the <strong>Gita Mandir</strong> because the <strong>Bhagavad Gita is inscribed on its pillars</strong>, making the temple a place to read as well as pray. A tall <em>Gita Stambh</em> adds to the effect.</p>', '<p>Gita Mandir (Birla Mandir) is in Mathura–Vrindavan road. A calm red sandstone temple on the Mathura–Vrindavan road, with the Bhagavad Gita inscribed on its pillars. Usual darshan hours in summer: morning 5:00 am – 12:00 noon, evening 2:00 pm – 9:00 pm.</p>', '[{"id":"g1","label":"Name in Hindi","value":"बिरला मंदिर (गीता मंदिर)"},{"id":"g2","label":"Location","value":"Mathura–Vrindavan road"},{"id":"g3","label":"Type","value":"Modern Temple"},{"id":"g4","label":"Darshan","value":"Morning to midday, afternoon to evening"},{"id":"g5","label":"Dress code","value":"Modest clothing that covers shoulders and knees; shoes off outside."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q2","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Modern Temple","featured":false,"sortOrder":"20","timingNote":"Morning to midday, afternoon to evening","stats":[],"darshan":[{"id":"d1","season":"Summer","session":"Morning","time":"5:00 am – 12:00 noon","note":""},{"id":"d2","season":"Summer","session":"Evening","time":"2:00 pm – 9:00 pm","note":""},{"id":"d3","season":"Winter","session":"Morning","time":"5:30 am – 12:00 noon","note":""},{"id":"d4","season":"Winter","session":"Evening","time":"2:00 pm – 8:30 pm","note":""}],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing that covers shoulders and knees; shoes off outside."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"It is a calm, spacious, uncrowded place, perfect for seniors and for a mid-afternoon rest on the road between Mathura and Vrindavan. Spend ten minutes reading the verses on the pillars. Many of my guests say this was their quietest stop."}],"goodToKnow":"","address":{"street":"","locality":"Mathura–Vrindavan road","city":"Mathura","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Gita Mandir Birla Mandir Mathura","latitude":"","longitude":"","routes":[{"id":"r1","from":"Vrindavan","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"Frequent express trains reach Mathura Junction (MTJ) in about 2 to 3 hours, or drive the Yamuna Expressway in about 3 to 3.5 hours."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km","how":"Around 1 to 1.5 hours by road. Trains from Agra Cantt are frequent and quick."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"krishna-janmabhoomi"},{"id":"l2","slug":"dwarkadhish"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published'),
  ('Bhuteshwar Mahadev', 'Mathura', 'bhuteshwar-mahadev', '{"title":"Bhuteshwar Mahadev, Mathura: Timings & Guide","description":"One of Mathura''s most ancient Shiva shrines, where Shiva is honoured as the guardian of Krishna''s land. Darshan timings, how to reach and local tips."}'::jsonb, '{"title":"Bhuteshwar Mahadev","description":"One of Mathura''s most ancient Shiva shrines, where Shiva is honoured as the guardian of Krishna''s land."}'::jsonb, '', '', 'One of Mathura''s most ancient Shiva shrines, where Shiva is honoured as the guardian of Krishna''s land.', '', '', '', '', '', '<p>Bhuteshwar Mahadev is one of Mathura''s most ancient Shiva shrines. In Braj tradition, <strong>Shiva is the guardian of Mathura</strong>, the Kshetrapal who protects Krishna''s land, and a pilgrimage to Mathura is traditionally incomplete without his darshan. The temple is also counted as a Shakti Peeth.</p>', '<p>Bhuteshwar Mahadev is in Mathura. One of Mathura''s most ancient Shiva shrines, where Shiva is honoured as the guardian of Krishna''s land.</p>', '[{"id":"g1","label":"Location","value":"Mathura, Uttar Pradesh"},{"id":"g2","label":"Type","value":"Shiva Temple"},{"id":"g3","label":"Darshan","value":"Early morning until night, generally"},{"id":"g4","label":"Dress code","value":"Modest clothing that covers shoulders and knees; shoes off outside."}]'::jsonb, '{"heading":"Why book with Mathura Vrindavan Trips","intro":"Since 2015, Harsh Sharma and a team of local Brijwasis have guided pilgrims through these lanes, with a 4.9-star rating from our guests.","rows":[{"id":"w1","reason":"Local Brijwasi guides","detail":"A team born and raised in Braj, who know the right lane at the right hour."},{"id":"w2","reason":"Darshan planned around timings","detail":"We reconfirm temple timings the day before and plan around crowd patterns."},{"id":"w3","reason":"Clear written quotes","detail":"Customised packages with no hidden charges."},{"id":"w4","reason":"Gentle on seniors and families","detail":"Gentler routes, rest breaks and e-rickshaw or wheelchair help."},{"id":"w5","reason":"Stays arranged for you","detail":"Simple ashram stays or comfortable hotels near the major temples."}],"outro":"Tell us your dates and who is travelling, and we will reply with a plan that suits you."}'::jsonb, '[{"id":"q1","question":"What is the dress code for Braj temples?","answer":"Modest clothing that covers shoulders and knees. Slip-on footwear is practical because you will remove it often."},{"id":"q2","question":"Is there an entry fee for temples in Mathura and Vrindavan?","answer":"Nearly all are free to enter, with donations optional. A few places may charge a small fee for specific sections, special darshan or museums."}]'::jsonb, '{"category":"Shiva Temple","featured":false,"sortOrder":"21","timingNote":"Early morning until night, generally","stats":[],"darshan":[],"aarti":[],"visiting":[{"id":"v1","label":"Dress code","value":"Modest clothing that covers shoulders and knees; shoes off outside."}],"significance":"","festivals":[],"tips":[{"id":"t1","text":"Visit in the morning or on a Monday if you want a devotional atmosphere. Offer simple bel leaves and water, and skip anyone offering \"special pujas\" from the roadside."}],"goodToKnow":"","address":{"street":"","locality":"Mathura","city":"Mathura","state":"Uttar Pradesh","postalCode":""},"mapUrl":"","mapQuery":"Bhuteshwar Mahadev Temple Mathura","latitude":"","longitude":"","routes":[{"id":"r1","from":"Vrindavan","distance":"Roughly 11 to 15 km","how":"30 to 45 minutes by road, longer on festival days."},{"id":"r2","from":"Delhi","distance":"Roughly 160 to 180 km","how":"Frequent express trains reach Mathura Junction (MTJ) in about 2 to 3 hours, or drive the Yamuna Expressway in about 3 to 3.5 hours."},{"id":"r3","from":"Agra","distance":"About 55 to 60 km","how":"Around 1 to 1.5 hours by road. Trains from Agra Cantt are frequent and quick."}],"gallery":[],"nearby":[],"related":[{"id":"l1","slug":"krishna-janmabhoomi"},{"id":"l2","slug":"vishram-ghat"}],"sections":[],"order":["quickAnswer","glance","visitor","overview","history","guide","festivals","reach","gallery","tips","enquiry","nearby","whyBook","faqs"],"hidden":[],"updatedOn":""}'::jsonb, 'published')
